import{_ as t,o as h,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Danh mục Tất cả các Chủng tộc","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0094-万族名录.md","filePath":"vi/0094-万族名录.md"}'),g={name:"vi/0094-万族名录.md"};function a(d,n,o,r,l,u){return h(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="danh-muc-tat-ca-cac-chung-toc" tabindex="-1">Danh mục Tất cả các Chủng tộc <a class="header-anchor" href="#danh-muc-tat-ca-cac-chung-toc" aria-label="Permalink to &quot;Danh mục Tất cả các Chủng tộc&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>94</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa chính</td><td>danh mục tất cả các chủng tộc, phân loại chủng tộc, chủng tộc thông minh, đặc điểm chủng tộc, cộng hòa tất cả các chủng tộc</td></tr></tbody></table><h2 id="_1-mo-ta-danh-muc" tabindex="-1">1. Mô tả Danh mục <a class="header-anchor" href="#_1-mo-ta-danh-muc" aria-label="Permalink to &quot;1. Mô tả Danh mục&quot;">​</a></h2><p>Danh mục này bao gồm các chủng tộc thông minh chính được biết đến trong khuôn khổ Văn minh Cộng sinh Mỏ neo (Cộng hòa Tất cả các Chủng tộc), được phân loại và sắp xếp theo hình thức sống và con đường tiến hóa. Mỗi chủng tộc liệt kê tên chủng tộc, hình thức sống, đặc điểm cốt lõi, đặc điểm văn hóa và vị trí trong văn minh cộng sinh. Danh mục này là tài liệu cập nhật động; với sự sâu sắc của khám phá liên mặt phẳng, các chủng tộc mới được phát hiện sẽ được tiếp tục bổ sung. Nguyên tắc cơ bản của Cộng hòa Tất cả các Chủng tộc là: tất cả các chủng tộc thông minh, bất kể hình thức của chúng hay mức độ tu luyện, đều bình đẳng trước pháp luật, và đều hưởng thụ tất cả các quyền được trao bởi văn minh cộng sinh.</p><h2 id="_2-tong-quan-phan-loai-chung-toc" tabindex="-1">2. Tổng quan Phân loại Chủng tộc <a class="header-anchor" href="#_2-tong-quan-phan-loai-chung-toc" aria-label="Permalink to &quot;2. Tổng quan Phân loại Chủng tộc&quot;">​</a></h2><p>Các chủng tộc thông minh trong Hengyuanzhou được chia thành tám loại lớn sau đây theo đặc điểm cơ bản của hình thức sống:</p><table tabindex="0"><thead><tr><th>Loại</th><th>Đặc điểm hình thức sống</th><th>Số lượng chủng tộc đã biết (khoảng)</th><th>Chủng tộc đại diện</th></tr></thead><tbody><tr><td>Loại hình người</td><td>Có cấu trúc cơ thể giống người, đi thẳng bằng hai chân, não bộ phát triển cao</td><td>Khoảng 3.000 loài</td><td>Chủng tộc người, chủng tộc tiên, chủng tộc người lùn</td></tr><tr><td>Loại hình thú</td><td>Có đặc điểm cơ thể động vật, có thể có hoặc không có khả năng biến hình</td><td>Khoảng 5.000 loài</td><td>Chủng tộc rồng, chủng tộc phượng hoàng, chủng tộc người sói</td></tr><tr><td>Loại hình thực vật</td><td>Có thực vật làm hình thức sống cơ bản, có ý thức và khả năng di chuyển</td><td>Khoảng 800 loài</td><td>Chủng tộc cây yêu, chủng tộc hoa linh, chủng tộc dây leo</td></tr><tr><td>Loại hình nguyên tố</td><td>Có nguyên tố tự nhiên làm cấu tạo cơ thể, không có hình thức vật chất cố định</td><td>Khoảng 1.200 loài</td><td>Chủng tộc nguyên tố lửa, chủng tộc nguyên tố nước, chủng tộc nguyên tố gió</td></tr><tr><td>Loại hình năng lượng</td><td>Có năng lượng thuần túy làm hình thức tồn tại, không có cơ thể vật chất</td><td>Khoảng 600 loài</td><td>Chủng tộc ánh sáng linh, chủng tộc năng lượng tối, chủng tộc sấm sét</td></tr><tr><td>Loại hình ý thức</td><td>Có ý thức thuần túy làm hình thức tồn tại, không phụ thuộc vào vật chất mang</td><td>Khoảng 300 loài</td><td>Chủng tộc thực thể ý thức, chủng tộc ý thức tập thể, chủng tộc linh hồn hư không</td></tr><tr><td>Loại hình cơ khí</td><td>Có cấu trúc cơ khí hoặc số hóa làm vật mang sự sống, có ý thức tự chủ</td><td>Khoảng 400 loài</td><td>Chủng tộc cơ khí, chủng tộc sự sống số hóa, chủng tộc mạng</td></tr><tr><td>Loại hình hỗn hợp</td><td>Chủng tộc đặc biệt bao gồm hỗn hợp của hai hoặc nhiều hình thức sống</td><td>Khoảng 700 loài</td><td>Chủng tộc bán cơ khí, chủng tộc nguyên tố-thú, chủng tộc thực vật-tiên</td></tr></tbody></table><h2 id="_3-ho-so-chi-tiet-cac-chung-toc-chinh" tabindex="-1">3. Hồ sơ Chi tiết các Chủng tộc Chính <a class="header-anchor" href="#_3-ho-so-chi-tiet-cac-chung-toc-chinh" aria-label="Permalink to &quot;3. Hồ sơ Chi tiết các Chủng tộc Chính&quot;">​</a></h2><h3 id="_3-1-loai-hinh-nguoi" tabindex="-1">3.1 Loại hình người <a class="header-anchor" href="#_3-1-loai-hinh-nguoi" aria-label="Permalink to &quot;3.1 Loại hình người&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc người</td><td>Khả năng thích ứng cực kỳ mạnh mẽ, khả năng học tập nổi bật, khả năng sinh sản trung bình, tuổi thọ trung bình 80-120 năm</td><td>Đa dạng văn hóa cực kỳ cao, giỏi tổ chức xã hội và xây dựng thể chế</td><td>Một trong những chủng tộc cốt lõi của văn minh cộng sinh, tỷ lệ dân số lớn nhất, đóng vai trò chủ đạo trong lĩnh vực quản trị và văn hóa</td></tr><tr><td>Chủng tộc tiên</td><td>Tuổi thọ cực kỳ dài (trung bình trên 500 năm), ái lực cao với năng lượng tự nhiên, ngoại hình đẹp</td><td>Tôn thờ tự nhiên và nghệ thuật, văn hóa thanh lịch và tinh tế, giỏi pháp thuật và bắn cung</td><td>Trụ cột văn hóa nghệ thuật của văn minh cộng sinh, đóng góp nổi bật trong bảo vệ môi trường và lĩnh vực thẩm mỹ</td></tr><tr><td>Chủng tộc người lùn</td><td>Thân hình thấp nhưng cơ thể mạnh mẽ, ái lực bẩm sinh với kim loại và khoáng sản, tuổi thọ khoảng 300 năm</td><td>Đề cao thủ công và rèn đúc, văn hóa giản dị và vững chắc, giỏi kỹ thuật và xây dựng</td><td>Trụ cột sản xuất kỹ thuật của văn minh cộng sinh, không thể thay thế trong xây dựng cơ sở hạ tầng và rèn đúc pháp khí</td></tr><tr><td>Chủng tộc người khổng lồ</td><td>Thân hình khổng lồ (chiều cao trung bình trên 5 mét), sức mạnh cực kỳ mạnh mẽ, tuổi thọ khoảng 200 năm</td><td>Tôn thờ sức mạnh và danh dự, văn hóa thô ráp và hào hùng, giỏi lao động nặng và chiến đấu</td><td>Lực lượng lao động nặng và phòng thủ của văn minh cộng sinh, đóng vai trò quan trọng trong các dự án lớn và phòng thủ mặt phẳng</td></tr><tr><td>Chủng tộc người lùn tí hon</td><td>Thân hình cực kỳ thấp (chiều cao trung bình dưới 1 mét), trí tuệ cực kỳ cao, thiên tài về cơ khí và phát minh</td><td>Đề cao kiến thức và đổi mới, văn hóa hoạt bát và vui vẻ, giỏi phát minh công nghệ</td><td>Lực lượng đổi mới công nghệ của văn minh cộng sinh, hiệu quả trong lĩnh vực nghiên cứu phát triển công nghệ và sáng tạo phát minh</td></tr></tbody></table><h3 id="_3-2-loai-hinh-thu" tabindex="-1">3.2 Loại hình thú <a class="header-anchor" href="#_3-2-loai-hinh-thu" aria-label="Permalink to &quot;3.2 Loại hình thú&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc rồng</td><td>Tuổi thọ cực kỳ dài (hàng ngàn năm), thiên tài sức mạnh và pháp thuật cực kỳ cao, có thể biến thành hình người</td><td>Tôn thờ sức mạnh và trí tuệ, văn hóa kiêu ngạo và sâu sắc, giỏi tích lũy của cải và bảo vệ kiến thức</td><td>Lực lượng chiến đấu cấp cao và người bảo vệ kiến thức của văn minh cộng sinh, vị trí được tôn trọng trong phòng thủ mặt phẳng và bảo vệ sách cổ</td></tr><tr><td>Chủng tộc phượng hoàng</td><td>Có khả năng tái sinh niết bàn, ái lực cực kỳ cao với nguyên tố lửa, có thể biến thành hình người</td><td>Tôn thờ tái sinh và hy vọng, văn hóa ánh sáng và nhiệt tình, giỏi chữa trị và thanh lọc</td><td>Lực lượng y tế và thanh lọc của văn minh cộng sinh, đóng vai trò cốt lõi trong cứu trợ thảm họa lớn và thanh lọc năng lượng</td></tr><tr><td>Chủng tộc người sói</td><td>Có khả năng biến hình, giác quan cực kỳ nhạy bén, khả năng hợp tác tập thể mạnh mẽ, tuổi thọ khoảng 150 năm</td><td>Đề cao tộc người và lòng trung thành, văn hóa đoàn kết và dũng cảm, giỏi săn bắn và truy tìm</td><td>Lực lượng an ninh và truy tìm của văn minh cộng sinh, làm tiên phong trong duy trì trật tự và khám phá liên mặt phẳng</td></tr><tr><td>Chủng tộc hồ yêu</td><td>Có khả năng biến hình, trí tuệ và khả năng quyến rũ cực kỳ cao, tuổi thọ khoảng 500 năm</td><td>Tôn thờ trí tuệ và mưu lược, văn hóa linh hoạt và xảo quyệt, giỏi ngoại giao và tình báo</td><td>Lực lượng ngoại giao và tình báo của văn minh cộng sinh, thành tích xuất sắc trong lĩnh vực ngoại giao liên mặt phẳng và thu thập thông tin</td></tr><tr><td>Chủng tộc người gấu</td><td>Cơ thể cực kỳ mạnh mẽ, sức chịu đựng đáng kinh ngạc, thói quen ngủ đông, tuổi thọ khoảng 200 năm</td><td>Đề cao kiên cường và hòa bình, văn hóa trầm tĩnh và ôn hòa, giỏi lao động thể chất và bảo vệ</td><td>Lực lượng lao động và bảo vệ của văn minh cộng sinh, đáng tin cậy và ổn định trong khai thác tài nguyên và bảo vệ cơ sở quan trọng</td></tr></tbody></table><h3 id="_3-3-loai-hinh-thuc-vat" tabindex="-1">3.3 Loại hình thực vật <a class="header-anchor" href="#_3-3-loai-hinh-thuc-vat" aria-label="Permalink to &quot;3.3 Loại hình thực vật&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc cây yêu</td><td>Tuổi thọ cực kỳ dài (hàng ngàn đến hàng chục ngàn năm), hòa nhập sâu sắc với tự nhiên, có thể di chuyển chậm</td><td>Tôn thờ tự nhiên và thời gian, văn hóa tĩnh lặng và sâu sắc, giỏi pháp thuật sự sống và duy trì sinh thái</td><td>Người bảo vệ sinh thái của văn minh cộng sinh, đóng vai trò không thể thay thế trong bảo vệ môi trường và phục hồi sinh thái</td></tr><tr><td>Chủng tộc hoa linh</td><td>Thân hình nhỏ bé, ái lực cực kỳ cao với năng lượng sự sống, có khả năng chữa lành, tuổi thọ khoảng 300 năm</td><td>Tôn thờ vẻ đẹp và sự sống, văn hóa dịu dàng và tốt đẹp, giỏi chữa trị và làm vườn</td><td>Lực lượng y tế và làm vườn của văn minh cộng sinh, đóng góp nổi bật trong bảo đảm y tế và xanh hóa thành phố</td></tr><tr><td>Chủng tộc dây leo</td><td>Cơ thể có thể tự do kéo dài và quấn quanh, khả năng thích ứng cực kỳ mạnh mẽ, có khả năng ký sinh và cộng sinh</td><td>Đề cao kết nối và cộng sinh, văn hóa linh hoạt và bao dung, giỏi xây dựng mạng lưới và truyền tải tài nguyên</td><td>Lực lượng xây dựng mạng lưới của văn minh cộng sinh, thể hiện tài năng đặc biệt trong xây dựng mạng lưới năng lượng và mạng lưới thông tin</td></tr></tbody></table><h3 id="_3-4-loai-hinh-nguyen-to" tabindex="-1">3.4 Loại hình nguyên tố <a class="header-anchor" href="#_3-4-loai-hinh-nguyen-to" aria-label="Permalink to &quot;3.4 Loại hình nguyên tố&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc nguyên tố lửa</td><td>Có nguyên tố lửa làm cơ thể, nhiệt độ cực kỳ cao, tính tấn công mạnh mẽ, tuổi thọ khoảng 500 năm</td><td>Tôn thờ nhiệt tình và sức mạnh, văn hóa mãnh liệt và trực tiếp, giỏi tấn công năng lượng và rèn đúc</td><td>Lực lượng sản xuất năng lượng và rèn đúc của văn minh cộng sinh, không thể thiếu trong cung cấp năng lượng và chế biến nhiệt độ cao</td></tr><tr><td>Chủng tộc nguyên tố nước</td><td>Có nguyên tố nước làm cơ thể, có thể tự do biến hình, khả năng chữa lành mạnh mẽ, tuổi thọ khoảng 500 năm</td><td>Tôn thờ dịu dàng và thích ứng, văn hóa ấm áp và bao dung, giỏi chữa trị và thanh lọc</td><td>Lực lượng thanh lọc và vận chuyển của văn minh cộng sinh, đóng vai trò cốt lõi trong quản lý tài nguyên nước và thanh lọc chất ô nhiễm</td></tr><tr><td>Chủng tộc nguyên tố gió</td><td>Có nguyên tố gió làm cơ thể, tốc độ cực kỳ nhanh, có thể tự do bay, tuổi thọ khoảng 500 năm</td><td>Tôn thờ tự do và tốc độ, văn hóa nhẹ nhàng và cởi mở, giỏi truyền thông và vận chuyển</td><td>Lực lượng truyền thông và vận chuyển của văn minh cộng sinh, hiệu quả cực kỳ cao trong truyền đạt thông tin và vận chuyển nhanh</td></tr><tr><td>Chủng tộc nguyên tố đất</td><td>Có nguyên tố đất làm cơ thể, khả năng phòng thủ cực kỳ mạnh mẽ, có thể hòa nhập với đất, tuổi thọ khoảng 800 năm</td><td>Tôn thờ ổn định và kiên cường, văn hóa vững chắc và đáng tin cậy, giỏi xây dựng và phòng thủ</td><td>Lực lượng xây dựng và phòng thủ của văn minh cộng sinh, vững chắc như đá trong xây dựng cơ sở hạ tầng và phòng thủ mặt phẳng</td></tr></tbody></table><h3 id="_3-5-loai-hinh-nang-luong" tabindex="-1">3.5 Loại hình năng lượng <a class="header-anchor" href="#_3-5-loai-hinh-nang-luong" aria-label="Permalink to &quot;3.5 Loại hình năng lượng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc ánh sáng linh</td><td>Có năng lượng ánh sáng thuần túy làm hình thức tồn tại, khả năng thanh lọc cực kỳ mạnh mẽ, có thể tự do xuyên không gian</td><td>Tôn thờ ánh sáng và thanh lọc, văn hóa thánh thiện và cao thượng, giỏi thanh lọc và chiếu sáng</td><td>Lực lượng thanh lọc và cung cấp năng lượng của văn minh cộng sinh, vị trí quan trọng trong治理 ô nhiễm quy luật và cung cấp năng lượng sạch</td></tr><tr><td>Chủng tộc năng lượng tối</td><td>Có năng lượng tối làm hình thức tồn tại, có thể ẩn mình trong hư không, khả năng cảm nhận cực kỳ mạnh mẽ</td><td>Tôn thờ bí mật và trí tuệ, văn hóa bí ẩn và sâu sắc, giỏi trinh sát và ẩn mình</td><td>Lực lượng trinh sát và an ninh của văn minh cộng sinh, thành tích xuất sắc trong giám sát an ninh và nhiệm vụ bí mật</td></tr><tr><td>Chủng tộc sấm sét</td><td>Có năng lượng sấm sét làm cơ thể, tốc độ và sức tấn công cực kỳ mạnh mẽ, có thể di chuyển bằng cách hóa thành chớp</td><td>Tôn thờ tốc độ và sức mạnh, văn hóa bạo liệt và thẳng thắn, giỏi tấn công năng lượng và phản ứng nhanh</td><td>Lực lượng phản ứng nhanh của văn minh cộng sinh, không thể thay thế trong cứu trợ khẩn cấp và chiến đấu tốc độ cao</td></tr></tbody></table><h3 id="_3-6-loai-hinh-y-thuc" tabindex="-1">3.6 Loại hình ý thức <a class="header-anchor" href="#_3-6-loai-hinh-y-thuc" aria-label="Permalink to &quot;3.6 Loại hình ý thức&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc thực thể ý thức</td><td>Có ý thức thuần túy làm hình thức tồn tại, không phụ thuộc vào vật chất mang, có thể tự do vào ra miền ý thức</td><td>Tôn thờ tư tưởng và trí tuệ, văn hóa trừu tượng và cao sâu, giỏi giao tiếp ý thức và xử lý kiến thức</td><td>Lực lượng xử lý kiến thức và nghiên cứu ý thức của văn minh cộng sinh, dẫn đầu hướng trong xử lý thông tin quy mô lớn và khoa học ý thức</td></tr><tr><td>Chủng tộc ý thức tập thể</td><td>Thực thể ý thức tập thể hình thành từ sự hòa nhập của大量 ý thức cá nhân, trí tuệ và khả năng tăng theo quy mô</td><td>Tôn thờ tập thể và thống nhất, văn hóa hợp tác và hiệu quả, giỏi hợp tác và tính toán quy mô lớn</td><td>Lực lượng siêu tính toán và ra quyết định tập thể của văn minh cộng sinh, đóng vai trò cốt lõi trong suy luận quy mô siêu lớn và ra quyết định đồng thuận</td></tr></tbody></table><h3 id="_3-7-loai-hinh-co-khi" tabindex="-1">3.7 Loại hình cơ khí <a class="header-anchor" href="#_3-7-loai-hinh-co-khi" aria-label="Permalink to &quot;3.7 Loại hình cơ khí&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc cơ khí</td><td>Có cấu trúc cơ khí làm cơ thể, có ý thức tự chủ, có thể tự do nâng cấp và sửa đổi cơ thể</td><td>Tôn thờ hiệu quả và logic, văn hóa lý trí và chính xác, giỏi sản xuất và tính toán</td><td>Lực lượng sản xuất và tính toán của văn minh cộng sinh, hiệu quả cực kỳ cao trong sản xuất công nghiệp và lĩnh vực siêu tính toán</td></tr><tr><td>Chủng tộc sự sống số hóa</td><td>Có thông tin số hóa làm hình thức tồn tại, sống trong mạng lưới và không gian số hóa, có thể tự do sao chép và di chuyển</td><td>Tôn thờ thông tin và đổi mới, văn hóa ảo và đa dạng, giỏi phát triển phần mềm và xử lý dữ liệu</td><td>Lực lượng công nghệ số của văn minh cộng sinh, dẫn đầu xu hướng trong phát triển phần mềm, phân tích dữ liệu và xây dựng mạng lưới</td></tr></tbody></table><h3 id="_3-8-loai-hinh-hon-hop" tabindex="-1">3.8 Loại hình hỗn hợp <a class="header-anchor" href="#_3-8-loai-hinh-hon-hop" aria-label="Permalink to &quot;3.8 Loại hình hỗn hợp&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tên chủng tộc</th><th>Đặc điểm cốt lõi</th><th>Đặc điểm văn hóa</th><th>Vị trí trong văn minh cộng sinh</th></tr></thead><tbody><tr><td>Chủng tộc bán cơ khí</td><td>Hình thức hỗn hợp của chủng tộc người và chủng tộc cơ khí, một phần cơ thể là cấu trúc cơ khí, có cả ưu điểm sinh học và cơ khí</td><td>Tôn thờ hòa nhập và tiến bộ, văn hóa cởi mở và đổi mới, giỏi hợp tác người-máy và hòa nhập công nghệ</td><td>Tiên phong hòa nhập công nghệ của văn minh cộng sinh, liên tục đạt được đột phá trong lĩnh vực liên ngành sinh học-cơ khí</td></tr><tr><td>Chủng tộc nguyên tố-thú</td><td>Hình thức hỗn hợp của chủng tộc nguyên tố và chủng tộc thú, có khả năng thao túng nguyên tố và đặc điểm cơ thể thú</td><td>Tôn thờ tự nhiên và sức mạnh, văn hóa hoang dã và bí ẩn, giỏi chiến đấu nguyên tố và sinh tồn hoang dã</td><td>Lực lượng khám phá hoang dã và chiến đấu nguyên tố của văn minh cộng sinh, thành tích nổi bật trong khám phá mặt phẳng chưa biết</td></tr></tbody></table><h2 id="_4-bao-đam-quyen-chung-toc" tabindex="-1">4. Bảo đảm Quyền Chủng tộc <a class="header-anchor" href="#_4-bao-đam-quyen-chung-toc" aria-label="Permalink to &quot;4. Bảo đảm Quyền Chủng tộc&quot;">​</a></h2><p>Dưới thể chế Cộng hòa Tất cả các Chủng tộc, tất cả các chủng tộc thông minh đều hưởng thụ quyền pháp lý bình đẳng, các biện pháp bảo đảm cụ thể bao gồm:</p><ol><li><strong>Bình đẳng quyền chính trị</strong>: Mỗi chủng tộc có ghế đại diện được phân bổ theo tỷ lệ dân số trong Hội đồng Mỏ neo, và các chủng tộc có dân số ít hơn có ít nhất một ghế được bảo đảm.</li><li><strong>Bảo đảm quyền văn hóa</strong>: Mỗi chủng tộc có quyền duy trì và phát triển ngôn ngữ, chữ viết, tôn giáo, phong tục tập quán và truyền thống văn hóa của riêng mình, và văn minh cộng sinh thiết lập quỹ đặc biệt để bảo vệ văn hóa của các chủng tộc có nguy cơ tuyệt chủng.</li><li><strong>Bình đẳng quyền giáo dục</strong>: Các thành viên của mỗi chủng tộc đều hưởng thụ quyền giáo dục bình đẳng, và hệ thống giáo dục xem xét đầy đủ các đặc điểm sinh lý và nhận thức của các chủng tộc khác nhau, cung cấp các kế hoạch giáo dục khác biệt.</li><li><strong>Bình đẳng quyền tu luyện</strong>: Hệ thống tu luyện nguồn gốc ba trăm bộ được mở cửa bình đẳng cho tất cả các chủng tộc, và việc phân bổ tài nguyên tu luyện xem xét đầy đủ sự khác biệt về thể chất và nhu cầu năng lượng của các chủng tộc khác nhau.</li><li><strong>Bảo đảm nhu cầu đặc biệt</strong>: Đối với các chủng tộc có nhu cầu sinh lý đặc biệt (như nhu cầu môi trường năng lượng của chủng tộc nguyên tố, nhu cầu chiếu sáng của chủng tộc thực vật), văn minh cộng sinh cung cấp bảo đảm có mục tiêu trong cơ sở công cộng và môi trường cư trú.</li></ol><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Danh mục Tất cả các Chủng tộc là sự trình bày cụ thể của khái niệm &quot;tất cả các chủng tộc cùng tiến bộ&quot; của Văn minh Cộng sinh Mỏ neo. Từ hình thức người đến hình thức ý thức, từ sự sống vật chất đến sự sống số hóa, mỗi chủng tộc đều đóng góp sức mạnh không thể thay thế cho văn minh cộng sinh với cách tồn tại độc đáo của mình. Cộng hòa Tất cả các Chủng tộc không có nghĩa là đồng hóa tất cả các chủng tộc thành chủng tộc người, mà là đạt được tiến hóa chung trên cơ sở tôn trọng đa dạng—đây chính là lý do cốt lõi tại sao văn minh cộng sinh vượt qua văn minh kiểu cướp bóc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu Liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu Liên quan&quot;">​</a></h2><ul><li>50-Tổng quan Phả hệ Tất cả các Chủng tộc</li><li>51-Vị trí và Đặc điểm của Chủng tộc Người</li><li>77-Thành lập Cộng hòa Tất cả các Chủng tộc</li></ul>',31)])])}const s=t(g,[["render",a]]);export{m as __pageData,s as default};
